def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = [[sorted_intervals[0][0], sorted_intervals[0][1]]]

    for i in range(1, len(sorted_intervals)):
        start, end = sorted_intervals[i]
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    unique_edges = set(edges)

    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in unique_edges:
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    batches = []
    current_batch = []
    current_weight = 0
    for name, weight in items:
        if current_weight + weight > limit:
            batches.append(current_batch)
            current_batch = []
            current_weight = 0
        current_batch.append(name)
        current_weight += weight
    if current_batch:
        batches.append(current_batch)
    return batches

import re

def parse_env(text):
    env = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '=' found): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2:
            if (value[0] == '"' and value[-1] == '"') or (value[0] == "'" and value[-1] == "'"):
                value = value[1:-1]

        env[key] = value

    return env

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    events = []
    current_data = []

    for line in lines:
        if line == '':
            if current_data:
                payload = '\n'.join(current_data)
                if payload == '[DONE]':
                    return events
                events.append(payload)
            current_data = []
        elif line.startswith('#'):
            continue
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            current_data.append(value)
        else:
            continue

    # Unterminated final event: ignore
    return events

def fifo_admit(active, queued, budget, slots):
    for item in queued:
        if item > budget:
            raise ValueError(
                f"Queued reservation {item} exceeds the whole budget {budget}"
            )

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    for item in queued:
        if remaining_slots > 0 and remaining_budget >= item:
            admitted.append(item)
            remaining_slots -= 1
            remaining_budget -= item
        else:
            break

    remaining = queued[len(admitted):]
    return (admitted, remaining)
